steps=[('Make a household plan','Choose contacts, meeting places and when you would leave.','/preparedness/household-emergency-plan/'),('Check what you already own','Take stock before buying more.','/preparedness/preparedness-inventory/'),('Cover the essentials','Prioritize useful supplies around your budget.','/preparedness/budget-preparedness/'),('Practice and maintain','Test your plan and fix one gap at a time.','/preparedness/preparedness-maintenance/')]
